{
  "characteristics": [
    {
      "tmf_name": "enabled",
      "json_type": "boolean",
      "description": "Controls whether or not Network address translation from IPv4 to IPv4 (NAT44) [RFC3022] is required."
    },
    {
      "tmf_name": "nat44-customer-address",
      "json_type": "string",
      "description": "Address to be used for network address translation from IPv4 to IPv4. This is to be used if the customer is providing the IPv4 address. If the customer address is not set, the model assumes that the provider will allocate the address."
    }
  ]
}

{
  "characteristics": [
    {
      "tmf_name": "id",
      "json_type": "integer",
      "description": "Unique identifier for the mapping."
    },
    {
      "tmf_name": "rp-address",
      "json_type": "string",
      "description": "Defines the address of the RP. Used if the RP is customer-managed."
    }
  ]
}

{
    "characteristics": [
        {
            "tmf_name": "vpn-id",
            "json_type": "string",
            "description": "Identifies the target VPN the local VPN want to access."
        },
        {
            "tmf_name": "local-sites-role",
            "json_type": "string",
            "description": "This describes the role of the local sites in the target VPN topology. In the any-to-any VPN service topology, the local sites must have the same role, which will be 'any-to-any-role'. In the Hub-and-Spoke VPN service topology or the Hub-and-Spoke disjoint VPN service topology, the local sites must have a Hub role or a Spoke role."
        }
    ]
}

{
  "characteristics": [
    {
      "tmf_name": "site-id",
      "json_type": "string",
      "description": "Identifier of the site."
    },
    {
      "tmf_name": "requested-site-start",
      "json_type": "string",
      "description": "Optional leaf indicating requested date and time when the service at a particular site is expected to start."
    },
    {
      "tmf_name": "requested-site-stop",
      "json_type": "string",
      "description": "Optional leaf indicating requested date and time when the service at a particular site is expected to stop."
    },
    {
      "tmf_name": "site-vpn-flavor",
      "json_type": "string",
      "description": "Defines the way the VPN multiplexing is done, e.g., whether the site belongs to a single VPN site or a multiVPN; or, in the case of a multiVPN, whether the logical accesses of the sites belong to the same set of VPNs or each logical access maps to different VPNs."
    },
    {
      "tmf_name": "actual-site-start",
      "json_type": "string",
      "description": "Optional leaf indicating actual date and time when the service at a particular site actually started."
    },
    {
      "tmf_name": "actual-site-stop",
      "json_type": "string",
      "description": "Optional leaf indicating actual date and time when the service at a particular site actually stopped."
    }
  ]
}

{
  "characteristics": [
    {
      "tmf_name": "location-id",
      "json_type": "string",
      "definition": "Identifier for a particular location."
    },
    {
      "tmf_name": "address",
      "json_type": "string",
      "definition": "Address (number and street) of the site."
    },
    {
      "tmf_name": "postal-code",
      "json_type": "string",
      "definition": "Postal code of the site."
    },
    {
      "tmf_name": "state",
      "json_type": "string",
      "definition": "State of the site. This leaf can also be used to describe a region for a country that does not have states."
    },
    {
      "tmf_name": "city",
      "json_type": "string",
      "definition": "City of the site."
    },
    {
      "tmf_name": "country-code",
      "json_type": "string",
      "definition": "Country of the site. Expressed as ISO ALPHA-2 code."
    }
  ]
}

{
